            public var running: Bool?

            public init(from decoder: any Decoder) throws {
                let c = try decoder.container(keyedBy: AnyCodingKey.self)
                allowedNodes = c.lenientArray(String.self, forKey: AnyCodingKey("allowed-nodes"))
                dependentHaResources = c.lenientArray(String.self, forKey: AnyCodingKey("dependent-ha-resources"))
                notAllowedNodes = try? c.decodeIfPresent(JSONValue.self, forKey: AnyCodingKey("not-allowed-nodes"))
                running = c.flexibleBool(AnyCodingKey("running"))
            }
        }
    }

    /// `POST /nodes/{node}/lxc/{vmid}/migrate`
    ///
    /// Migrate the container to another node. Creates a new migration task.
    public struct PostNodesLxcMigrate: PVEAPIRequest, Hashable {
        public typealias Response = String
        public static let method: HTTPMethod = .post
        public static let pathTemplate = "/nodes/{node}/lxc/{vmid}/migrate"
        public static let schemaName = "migrate_vm"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        /// The (unique) ID of the VM.
        ///
        /// Range: 100…999999999. Format: `pve-vmid`.
        public var vmid: Int

        /// Target node.
        ///
        /// Format: `pve-node`.
        public var target: String

        /// Override I/O bandwidth limit (in KiB/s).
        ///
        /// Default: `migrate limit from datacenter or storage config`. Minimum: 0.
        public var bwlimit: Double?

        /// Use online/live migration.
        public var online: Bool?

        /// Use restart migration
        public var restart: Bool?

        /// For intra-cluster migration. Skip checking if the configuration can be parsed successfully by the target. Using this flag can lead to dropped or ignored configuration options if the target is too old to parse them.
        ///
        /// Default: `0`.
        public var skipConfigCheck: Bool?

        /// Mapping from source to target storages. Providing only a single storage ID maps all source storages to that storage. Providing the special value '1' will map each source storage to itself.
        ///
        /// Format: `storage-pair-list`.
        public var targetStorage: String?

        /// Timeout in seconds for shutdown for restart migration
        ///
        /// Default: `180`.
        public var timeout: Int?

        public init(node: String, vmid: Int, target: String) {
            self.node = node
            self.vmid = vmid
            self.target = target
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "lxc", vmid.parameterValue, "migrate") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            result.append(("target", target.parameterValue))
            if let value = bwlimit { result.append(("bwlimit", value.parameterValue)) }
            if let value = online { result.append(("online", value.parameterValue)) }
            if let value = restart { result.append(("restart", value.parameterValue)) }
            if let value = skipConfigCheck { result.append(("skip-config-check", value.parameterValue)) }
            if let value = targetStorage { result.append(("target-storage", value.parameterValue)) }
            if let value = timeout { result.append(("timeout", value.parameterValue)) }
            return result
        }
    }

