    /// `POST /nodes/{node}/lxc/{vmid}/mtunnel`
    ///
    /// Migration tunnel endpoint - only for internal use by CT migration.
    public struct PostNodesLxcMtunnel: PVEAPIRequest, Hashable {
        public typealias Response = Output
        public static let method: HTTPMethod = .post
        public static let pathTemplate = "/nodes/{node}/lxc/{vmid}/mtunnel"
        public static let schemaName = "mtunnel"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        /// The (unique) ID of the VM.
        ///
        /// Range: 100…999999999. Format: `pve-vmid`.
        public var vmid: Int

        /// List of network bridges to check availability. Will be checked again for actually used bridges during migration.
        ///
        /// Format: `pve-bridge-id-list`.
        public var bridges: String?

        /// List of storages to check permission and availability. Will be checked again for all actually used storages during migration.
        ///
        /// Format: `pve-storage-id-list`.
        public var storages: String?

        public init(node: String, vmid: Int) {
            self.node = node
            self.vmid = vmid
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "lxc", vmid.parameterValue, "mtunnel") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            if let value = bridges { result.append(("bridges", value.parameterValue)) }
            if let value = storages { result.append(("storages", value.parameterValue)) }
            return result
        }

        public struct Output: Decodable, Sendable, Hashable {
            public var socket: String?
            public var ticket: String?
            public var upid: String?

            public init(from decoder: any Decoder) throws {
                let c = try decoder.container(keyedBy: AnyCodingKey.self)
                socket = c.flexibleString(AnyCodingKey("socket"))
                ticket = c.flexibleString(AnyCodingKey("ticket"))
                upid = c.flexibleString(AnyCodingKey("upid"))
            }
        }
    }

    /// `GET /nodes/{node}/lxc/{vmid}/mtunnelwebsocket`
    ///
    /// Migration tunnel endpoint for websocket upgrade - only for internal use by VM migration.
    public struct GetNodesLxcMtunnelwebsocket: PVEAPIRequest, Hashable {
        public typealias Response = Output
        public static let method: HTTPMethod = .get
        public static let pathTemplate = "/nodes/{node}/lxc/{vmid}/mtunnelwebsocket"
        public static let schemaName = "mtunnelwebsocket"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        /// The (unique) ID of the VM.
        ///
        /// Range: 100…999999999. Format: `pve-vmid`.
        public var vmid: Int

        /// unix socket to forward to
        public var socket: String

        /// ticket return by initial 'mtunnel' API call, or retrieved via 'ticket' tunnel command
        public var ticket: String

        public init(node: String, vmid: Int, socket: String, ticket: String) {
            self.node = node
            self.vmid = vmid
            self.socket = socket
            self.ticket = ticket
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "lxc", vmid.parameterValue, "mtunnelwebsocket") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            result.append(("socket", socket.parameterValue))
            result.append(("ticket", ticket.parameterValue))
            return result
        }

        public struct Output: Decodable, Sendable, Hashable {
            public var port: String?
            public var socket: String?

            public init(from decoder: any Decoder) throws {
                let c = try decoder.container(keyedBy: AnyCodingKey.self)
                port = c.flexibleString(AnyCodingKey("port"))
                socket = c.flexibleString(AnyCodingKey("socket"))
            }
        }
    }

