    /// `POST /nodes/{node}/lxc/{vmid}/remote_migrate`
    ///
    /// Migrate the container to another cluster. Creates a new migration task. EXPERIMENTAL feature!
    public struct PostNodesLxcRemoteMigrate: PVEAPIRequest, Hashable {
        public typealias Response = String
        public static let method: HTTPMethod = .post
        public static let pathTemplate = "/nodes/{node}/lxc/{vmid}/remote_migrate"
        public static let schemaName = "remote_migrate_vm"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        /// The (unique) ID of the VM.
        ///
        /// Range: 100…999999999. Format: `pve-vmid`.
        public var vmid: Int

        /// Mapping from source to target bridges. Providing only a single bridge ID maps all source bridges to that bridge. Providing the special value '1' will map each source bridge to itself.
        ///
        /// Format: `bridge-pair-list`.
        public var targetBridge: String

        /// Remote target endpoint
        ///
        /// Format: `proxmox-remote`.
        public var targetEndpoint: String

        /// Mapping from source to target storages. Providing only a single storage ID maps all source storages to that storage. Providing the special value '1' will map each source storage to itself.
        ///
        /// Format: `storage-pair-list`.
        public var targetStorage: String

        /// Allow the migration if another guest in the target cluster already has the uid of this guest. The migrated guest then gets a new uid.
        ///
        /// Default: `0`.
        public var allowNewUid: Bool?

        /// Override I/O bandwidth limit (in KiB/s).
        ///
        /// Default: `migrate limit from datacenter or storage config`. Minimum: 0.
        public var bwlimit: Double?

        /// Delete the original CT and related data after successful migration. By default the original CT is kept on the source cluster in a stopped state.
        ///
        /// Default: `0`.
        public var delete: Bool?

        /// Use online/live migration.
        public var online: Bool?

        /// Use restart migration
        public var restart: Bool?

        /// The (unique) ID of the VM.
        ///
        /// Range: 100…999999999. Format: `pve-vmid`.
        public var targetVmid: Int?

        /// Timeout in seconds for shutdown for restart migration
        ///
        /// Default: `180`.
        public var timeout: Int?

        public init(node: String, vmid: Int, targetBridge: String, targetEndpoint: String, targetStorage: String) {
            self.node = node
            self.vmid = vmid
            self.targetBridge = targetBridge
            self.targetEndpoint = targetEndpoint
            self.targetStorage = targetStorage
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "lxc", vmid.parameterValue, "remote_migrate") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            result.append(("target-bridge", targetBridge.parameterValue))
            result.append(("target-endpoint", targetEndpoint.parameterValue))
            result.append(("target-storage", targetStorage.parameterValue))
            if let value = allowNewUid { result.append(("allow-new-uid", value.parameterValue)) }
            if let value = bwlimit { result.append(("bwlimit", value.parameterValue)) }
            if let value = delete { result.append(("delete", value.parameterValue)) }
